// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // call succeeded
        } catch {
            // call reverted
        }
        // Rule: ownership can only be transferred by the current owner; since the
        // owner starts at address(0) and no caller can be address(0), owner must
        // remain address(0) after any attempt by any actor.
        assertTrue(c.owner() == address(0));
    }
}
